SELECT merchant, CASE WHEN amount >= 3700 THEN 'high' WHEN amount >= 1300 THEN 'mid' ELSE 'low' END AS amount_bucket, COUNT(DISTINCT amount) AS unique_accounts, COUNT(CASE WHEN txn_type = 'REFUND' THEN 1 END) AS refund_count FROM transactions WHERE is_flagged GROUP BY merchant, CASE WHEN amount >= 3700 THEN 'high' WHEN amount >= 1300 THEN 'mid' ELSE 'low' END HAVING COUNT(CASE WHEN txn_type = 'REFUND' THEN 1 END) > 4 ORDER BY merchant, unique_accounts DESC
